using EZapi;
using System.Text;
using System.Text.Json;
int passed=0;
void Check(bool ok,string name){if(!ok)throw new Exception(name);passed++;}
void Reject(Action action,string name){try{action();}catch(Exception){passed++;return;}throw new Exception(name);}
var context=new FactionUiContext(new(5,"run",10),"zh");
FactionUiDefinition D(string id="author.guild.faction")=>new(id,new("自由商会","Free traders"));
FactionReputationView S(double value=12)=>new(value){Perks=new[]{new FactionPerkView("author.guild.discount",new("折扣","Discount"),new("交易折扣","Trade discount"),60,false)}};
var catalog=new FactionUiCatalog();
Check(catalog.Register("author.guild",D(),_=>S()).Status==PresentationStatus.Queued,"register read-only provider");
Check(catalog.Register("author.guild",D(),_=>S()).Status==PresentationStatus.Conflict,"duplicate conflicts");
Check(catalog.Register("other",D("author.guild.other"),_=>S()).Status==PresentationStatus.Invalid,"cross-owner registration rejected");
Check(catalog.Remove("author","author.guild.faction").Status==PresentationStatus.Conflict,"parent namespace cannot remove child owner");
Check(catalog.Remove("other","author.guild.faction").Status==PresentationStatus.Invalid,"foreign removal rejected");
var state=catalog.Read(context,()=>true).Single();
Check(state.State.Amount==12&&state.Definition.Name.ForLocale("en")=="Free traders","snapshot uses supplied state and locale text");
Check(FactionUiRules.Matches(state,"free traders","en")&&!FactionUiRules.Matches(state,"not here","en"),"multi-word name filter");
Check(FactionUiRules.Matches(state,"author.guild","zh"),"stable-ID filter independent of locale");
Check(FactionUiRules.Position(-250,-200,200)==0&&FactionUiRules.Position(0,-200,200)==.5&&FactionUiRules.Position(250,-200,200)==1,"ruler clamps to configured range");
var perk=S().Perks[0];
Check(FactionUiRules.Progress(30,perk)==.5&&FactionUiRules.Progress(-30,perk)==0,"positive threshold directional progress");
Check(FactionUiRules.Progress(-30,perk with{Threshold=-60})==.5&&FactionUiRules.Progress(30,perk with{Threshold=-60})==0,"negative threshold directional progress");
Check(FactionUiRules.Progress(-500,perk with{Active=true})==1,"active state is authoritative");
Check(FactionUiRules.Progress(0,perk with{AlwaysActive=true})==1,"always-active bypasses threshold");
var list=new List<FactionPerkView>{perk};catalog.Register("author.guild",D("author.guild.copy"),_=>new(3){Perks=list});
var frozen=catalog.Read(context,()=>true).Single(r=>r.Definition.Id=="author.guild.copy");list.Clear();
Check(frozen.State.Perks.Count==1,"provider-owned list mutation cannot alter returned snapshot");
catalog.Register("author.guild",D("author.guild.broken"),_=>throw new InvalidOperationException("private details"));
catalog.Register("author.guild",D("author.guild.nan"),_=>S(double.NaN));
Check(catalog.Read(context,()=>true).Count==2&&catalog.Errors.Count==2,"one bad provider cannot disable other factions");
Check(!catalog.Errors.Values.Any(e=>e.Contains("private details")),"diagnostic only retains error class");
catalog.Register("author.guild",D("author.guild.hidden"),_=>null);
Check(catalog.Read(context,()=>true).Count==2,"null provider hides faction");
PresentationStatus reentry=default;
catalog.Register("author.guild",D("author.guild.reentry"),_=>{reentry=catalog.Remove("author.guild","author.guild.faction").Status;return S();});
catalog.Read(context,()=>true);Check(reentry==PresentationStatus.Conflict&&catalog.Entries.ContainsKey("author.guild.faction"),"provider cannot mutate registrations while enumerating");
var stale=new FactionUiCatalog();bool current=true;stale.Register("author.guild",D(),_=>{current=false;return S();});
Check(stale.Read(context,()=>current).Count==0,"run invalidation discards provider result");
foreach(var bad in new[]{D() with{Minimum=0},D() with{Maximum=0},D() with{Maximum=double.NaN},D() with{Color="red"},D() with{Name=new(" ","x")},D() with{Id="bad/id"}})
 Check(new FactionUiCatalog().Register("author.guild",bad,_=>S()).Status==PresentationStatus.Invalid,"invalid declaration rejected");
Reject(()=>FactionUiRules.Copy(S() with{Perks=new[]{perk,perk}}),"duplicate perk IDs rejected");
Reject(()=>FactionUiRules.Copy(S() with{Perks=new[]{perk with{Threshold=double.PositiveInfinity}}}),"nonfinite threshold rejected");
Reject(()=>FactionUiRules.Copy(S() with{Perks=new[]{perk with{Icon="unknown"}}}),"unknown icon rejected");
Reject(()=>FactionUiRules.Copy(S() with{Perks=Enumerable.Range(0,257).Select(i=>perk with{Id="perk.n"+i}).ToArray()}),"bounded perk count");
FactionUiDefinition Parse(string json)=>FactionUiJson.Parse(new MemoryStream(Encoding.UTF8.GetBytes(json)));
const string valid="{\"id\":\"author.guild.faction\",\"name\":{\"chinese\":\"自由商会\",\"english\":\"Free traders\"},\"color\":\"#71546d\",\"minimum\":-200,\"maximum\":200}";
Check(Parse(valid).Name.ForLocale("en")=="Free traders","JSON parsed from actual definition");
foreach(var json in new[]{valid.Replace("\"id\":","\"unknown\":1,\"id\":"),valid.Replace("\"name\":","\"NAME\":{},\"name\":"),valid.Replace("\"chinese\":","\"key\":\"not-supported\",\"chinese\":"),"{}","null",valid.Replace("-200","0"),new string(' ',17000)})
 Reject(()=>Parse(json),"malformed/duplicate/oversized JSON rejected");
FactionUiApi.Start();Check(FactionUiApi.Register("author.guild",D(),_=>S()).Status==PresentationStatus.Queued,"public registration initialized");
var unordered=new[]{perk with{Id="negative",Threshold=-40},perk with{Id="high",Threshold=100},perk with{Id="same-a",Threshold=20},perk with{Id="same-b",Threshold=20},perk with{Id="zero",Threshold=0}};
Check(FactionUiRules.OrderedPerks(unordered).Select(p=>p.Id).SequenceEqual(new[]{"high","same-a","same-b","zero","negative"}),"native top-to-bottom threshold order, stable for equal thresholds");
Check(unordered[0].Id=="negative","display ordering never mutates native/provider source order");
var marks=FactionUiRules.Markers(unordered);
Check(marks.Length==4&&marks.Single(m=>m.Threshold==20).Perks.Select(p=>p.Id).SequenceEqual(new[]{"same-a","same-b"}),"coincident markers preserve every effect and stable group order");
Check(marks.Select(m=>FactionUiRules.Position(m.Threshold,-200,200)).SequenceEqual(new[]{.4,.5,.55,.75}),"markers map real thresholds to ruler positions, not evenly-spaced moods");
Check(FactionUiRules.NativeRange(0,unordered)==(-200,200),"native base ruler remains -200 to 200");
Check(FactionUiRules.NativeRange(-300,unordered.Append(perk with{Threshold=600}))==(-300,600),"native Mod effects outside base range remain visible");
var extended=Enumerable.Range(0,256).Select(n=>perk with{Id="effect."+n,Threshold=n%2==0?20:-20}).ToArray();
Check(FactionUiRules.Markers(extended).SelectMany(g=>g.Perks).Count()==256,"large same-threshold extension retains all effects");
var dense=FactionUiRules.Markers(Enumerable.Range(0,256).Select(n=>perk with{Id="dense."+n,Threshold=n}));
Check(dense.Length<30&&dense.SelectMany(g=>g.Perks).Select(p=>p.Id).Distinct().Count()==256,"dense extension markers avoid overlapping hit targets without dropping effects");
Check(dense.SelectMany(g=>g.Perks).Select(p=>p.Threshold).SequenceEqual(Enumerable.Range(0,256).Select(n=>(double)n)),"dense marker grouping keeps every actual threshold");
GameSession.OnThread=false;Check(FactionUiApi.Unregister("author.guild","author.guild.faction").Status==PresentationStatus.Unavailable,"off-thread mutation rejected");
GameSession.OnThread=true;FactionUiApi.Stop();Check(FactionUiApi.Catalog.Entries.Count==0,"shutdown releases providers");
Console.WriteLine(JsonSerializer.Serialize(new{passed,failed=0,scope="Real faction catalog/API/JSON/filter/range rules with native boundary stubs; no native rendering or reputation/save writes"}));
